def projectcard(p):
 n=name[p['id']];return f'''<article class="project-card" data-category="{p['cat']}" data-group="{p['group']}"><a href="project-{p['id']}.html"><div class="photo"><img src="../assets/{p['id']}-photo.jpg" alt="{n}" loading="lazy"><span class="photo-link">عرض المشروع ↗</span></div><div class="project-heading"><h3>{n}</h3><span>↗</span></div></a><p class="project-meta">{loc[p['location']]} · {cat[p['cat']]}</p><div class="project-data"><span>{ar_area(p['area'])}</span><span>{duration(p['duration'])}</span><span>{group[p['group']]}</span></div></article>'''

page('index.html','الرئيسية','''<section class="hero hero-film" aria-label="الملف التعريفي لبلاك للإنشاءات"><div class="hero-slides" aria-hidden="true"><div class="hero-slide is-active" style="background-image:url('../assets/nbc-photo.jpg')"></div><div class="hero-slide" style="background-image:url('../assets/hashem-photo.jpg')"></div><div class="hero-slide" style="background-image:url('../assets/dforma-photo.jpg')"></div><div class="hero-slide" style="background-image:url('../assets/neutral-photo.jpg')"></div></div><div class="hero-film-shade"></div><div class="hero-film-content"><span class="eyebrow">بلاك للإنشاءات / الملف التعريفي 2026</span><img class="hero-film-logo" src="../assets/logo-transparent.png" alt="بلاك للإنشاءات"><h1>نبني برؤية.<br><em>وننجز بإتقان.</em></h1><p>حلول البناء والتشطيب وإدارة المشاريع، بجودة تُلمس في كل مرحلة.</p><div class="actions"><a class="button light" href="profile.html">استكشف ملف الشركة ↗</a><a class="underlined" href="projects.html">شاهد مشاريعنا ↗</a></div></div><div class="hero-film-footer"><span class="hero-film-caption" aria-live="polite">01 / 04 &nbsp; مبنى مكاتب NBC الجديد</span><button class="hero-film-toggle" type="button" aria-label="إيقاف عرض الصور">إيقاف Ⅱ</button></div></section><section class="section" id="introduction"><div class="split-heading"><span class="eyebrow">فريق واحد. تنفيذ متكامل.</span><h2>رؤيتك تستحق<br><em>التميّز.</em></h2></div><div class="intro-columns"><p class="lead">نبني بهدف واضح، ونوفّق بين الخبرة الفنية والتنفيذ المنضبط وفهم أهداف كل مشروع.</p><div><p>من التخطيط والتنسيق المبكر حتى التنفيذ والتسليم، نعمل على ضبط النطاق والجودة والتكلفة والجدول الزمني. وتشمل خبراتنا الإنشاءات والتشطيبات والتجديد والأعمال المتخصصة.</p><a class="underlined" href="expertise.html">اكتشف خبراتنا ↗</a></div></div><div class="facts"><div><strong>2018</strong><span>بداية رحلتنا</span></div><div><strong>07</strong><span>قدرات أساسية متكاملة</span></div><div><strong>03</strong><span>خطوط أعمال متخصصة</span></div><div><strong>KSA</strong><span>نبني وفق طموحاتك</span></div></div></section><section class="section pale"><div class="section-title"><div><span class="eyebrow">أعمالنا</span><h2>من مواقع العمل.<br><em>إلى إنجازات ملموسة.</em></h2></div><a class="underlined" href="projects.html">جميع المشاريع ↗</a></div><div class="portfolio-carousel" aria-label="مشاريع مختارة"><div class="portfolio-track" id="portfolio-track">'''+''.join(projectcard(p) for p in projects)+'''</div><div class="portfolio-controls"><span class="portfolio-position" aria-live="polite">01 / 08</span><div><button type="button" class="portfolio-prev" aria-label="المشاريع السابقة">→</button><button type="button" class="portfolio-next" aria-label="المشاريع التالية">←</button></div></div></div></section><section class="section"><div class="section-title"><div><span class="eyebrow">خطوط أعمالنا</span><h2>احتياجات مختلفة.<br><em>ومعيار واحد.</em></h2></div></div><div class="collection-strip"><a href="collections.html#nova"><span>01 / التنفيذ السريع</span><h3>NOVA</h3><p>نطوّر المساحات<br>مع استمرار أعمالك.</p><b>استكشف NOVA ↗</b></a><a href="collections.html#aura"><span>02 / التشطيبات الراقية</span><h3>AURA</h3><p>حيث تلتقي الدقة<br>بالأناقة.</p><b>استكشف AURA ↗</b></a><a href="collections.html#velare"><span>03 / الفخامة الخاصة</span><h3>VELARE</h3><p>تفاصيل مصممة<br>لتتجاوز المألوف.</p><b>استكشف VELARE ↗</b></a></div></section>''')

principles=[('الاحترام أساس الشراكة','نتعامل مع العملاء والاستشاريين والشركاء وفرق العمل بمهنية واحترام.'),('نستمع أولاً لننفذ أفضل','نفهم الأولويات ونوائم خطتنا قبل بدء التنفيذ.'),('مشروع واحد وفريق واحد','نعمل مع جميع أطراف المشروع لتحقيق هدف مشترك.'),('الشفافية تبني الثقة','نتواصل بوضوح ونعالج التحديات مبكراً ونبقي الأطراف المعنية على اطلاع.')]
advantages=[('الالتزام بالمعايير','نسترشد بالأنظمة والأكواد والمواصفات المعتمدة ومتطلبات المشروع.'),('مرونة التنفيذ','نتكيّف مع أولويات المشروع مع الحفاظ على الجودة والسلامة.'),('تخطيط وضبط منظم','خطط واضحة ومسؤوليات محددة ورقابة منضبطة في كل مرحلة.'),('تنفيذ يحقق القيمة','نحسّن الأساليب والموارد والمشتريات دون الإخلال بالمعايير المطلوبة.'),('جودة بلا مساومة','نراقب المواد والأعمال والفحوصات والتسليم طوال التنفيذ.'),('السلامة في كل مرحلة','ندمج السلامة في التخطيط والعمل الميداني لحماية الأشخاص والممتلكات واستمرارية المشروع.')]
